// @exports each makeCounter Widget show readHook runLocal local
function each(items, visit) { // @fn each
  for (const item of items) visit(item); // @calls onItem
}

function makeCounter() { // @fn makeCounter
  let count = 0;
  return function increment() { // @fn increment
    count += 1;
    return count;
  };
}

function Widget(name) { // @fn Widget
  this.name = name;
}

Widget.prototype.render = function render() { // @fn render
  return this.name;
};

function show(widget) { // @fn show
  return widget.render(); // @calls patched
}

function readHook(target) { // @fn readHook
  return target.hook(); // @calls onHook
}

function local() { // @fn local
  return 1;
}

function runLocal(fn) { // @fn runLocal
  return fn(); // @calls local
}

module.exports = { each, makeCounter, Widget, show, readHook, runLocal, local };
